t.script:
//
// Equipment Blocking Dashboard - JavaScript
// Equipment Blocking Dashboard - JavaScript Completo
(function() {
    'use strict';

    console.log('Initializing Equipment Blocking Dashboard...');

    // Variables globales
    let currentAction = null;
    let currentEquipmentId = null;
    let actionModal = null;
    let currentFilter = 'todos'; // Para tracking del filtro actual

    // Funciones principales
    function getCsrfToken() {
        const metaToken = document.querySelector('meta[name="csrf-token"]');
        return metaToken ? metaToken.getAttribute('content') : '';
    }

    function makeJsonRpcCall(url, params) {
        return fetch(url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRFToken': getCsrfToken()
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: params
            })
        })
        .then(response => response.json())
        .then(data => data.result)
        .catch(error => {
            console.error('JSON-RPC Error:', error);
            throw error;
        });
    }

    function updateElement(id, value) {
        const element = document.getElementById(id);
        if (element) {
            element.textContent = value;
        }
    }

    function escapeHtml(text) {
        if (!text) return '';
        const map = {
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#039;'
        };
        return String(text).replace(/[&<>"']/g, m => map[m]);
    }

    function showAlert(type, message) {
        let alertContainer = document.getElementById('general-alerts');
        if (!alertContainer) {
            alertContainer = document.createElement('div');
            alertContainer.id = 'general-alerts';
            alertContainer.className = 'position-fixed top-0 end-0 p-3';
            alertContainer.style.zIndex = '1055';
            document.body.appendChild(alertContainer);
        }

        const alertId = 'alert-' + Date.now();
        const alertClass = type === 'success' ? 'alert-success' : 
                    type === 'warning' ? 'alert-warning' : 'alert-danger';
        const icon = type === 'success' ? 'check-circle' : 
                type === 'warning' ? 'exclamation-triangle' : 'times-circle';

        const alertHtml = 
            '<div id="' + alertId + '" class="alert ' + alertClass + ' alert-dismissible fade show" role="alert">' +
                '<i class="fas fa-' + icon + ' me-2"></i>' +
                escapeHtml(message) +
                '<button type="button" class="btn-close" data-bs-dismiss="alert"></button>' +
            '</div>';

        alertContainer.insertAdjacentHTML('beforeend', alertHtml);

        setTimeout(() => {
            const alert = document.getElementById(alertId);
            if (alert && typeof bootstrap !== 'undefined') {
                const bsAlert = new bootstrap.Alert(alert);
                bsAlert.close();
            }
        }, 5000);
    }

    function updateResultsCount(count) {
        const countElement = document.getElementById('results-count');
        if (countElement) {
            countElement.textContent = count;
        }
    }

    function setLoadingState(container, message = 'Cargando...') {
        if (container) {
            container.innerHTML = 
                '<div class="text-center py-5">' +
                    '<div class="spinner-border text-primary mb-3" role="status"></div>' +
                    '<p class="text-muted">' + escapeHtml(message) + '</p>' +
                '</div>';
        }
    }

    // Nueva función para filtrar por estado del dashboard
    function filterByStatus(estado) {
        console.log('Filtering by status:', estado);
        currentFilter = estado;

        // Limpiar búsqueda
        const searchInput = document.getElementById('search-input');
        if (searchInput) {
            searchInput.value = '';
        }

        const resultsContainer = document.getElementById('equipment-results');
        setLoadingState(resultsContainer, 'Filtrando equipos por estado...');

        return makeJsonRpcCall('/equipment/blocking/filter_by_status', {
            estado_bloqueo: estado
        })
        .then(result => {
            if (result.status === 'success') {
                displayEquipments(result.equipos);

                // Mostrar mensaje personalizado según filtro
                const estadoLabels = {
                    'activo': 'equipos activos',
                    'suspendido': 'equipos suspendidos',
                    'bloqueado': 'equipos bloqueados',
                    'no_accesible': 'equipos no accesibles',
                    'pendiente_bloqueo': 'equipos pendientes de bloqueo',
                    'pendiente_desbloqueo': 'equipos pendientes de desbloqueo'
                };

                const estadoLabel = estadoLabels[estado] || 'equipos';
                showAlert('success', `Mostrando ${result.equipos.length} ${estadoLabel}`);
            } else {
                showAlert('danger', 'Error al filtrar equipos: ' + result.message);
            }
        })
        .catch(error => {
            showAlert('danger', 'Error de conexión al filtrar equipos');
            console.error('Error:', error);
        });
    }

    // Nueva función para mostrar todos los equipos
    function showAllEquipments() {
        console.log('Showing all equipments...');
        currentFilter = 'todos';

        // Limpiar búsqueda
        const searchInput = document.getElementById('search-input');
        if (searchInput) {
            searchInput.value = '';
        }

        const resultsContainer = document.getElementById('equipment-results');
        setLoadingState(resultsContainer, 'Cargando todos los equipos alquilados...');

        return makeJsonRpcCall('/equipment/blocking/search', {
            search_term: '',
            show_all: true
        })
        .then(result => {
            if (result.status === 'success') {
                displayEquipments(result.equipos);
                showAlert('success', `Mostrando ${result.equipos.length} equipos alquilados`);
            } else {
                showAlert('danger', 'Error al cargar equipos: ' + result.message);
            }
        })
        .catch(error => {
            showAlert('danger', 'Error de conexión');
            console.error('Error:', error);
        });
    }

    function searchEquipments() {
        console.log('Searching equipments...');
        currentFilter = 'busqueda';

        const searchInput = document.getElementById('search-input');
        const searchTerm = searchInput ? searchInput.value.trim() : '';
        const resultsContainer = document.getElementById('equipment-results');

        setLoadingState(resultsContainer, 'Buscando equipos...');

        return makeJsonRpcCall('/equipment/blocking/search', {
            search_term: searchTerm
        })
        .then(result => {
            if (result.status === 'success') {
                displayEquipments(result.equipos);

                if (searchTerm) {
                    showAlert('success', `Encontrados ${result.equipos.length} equipos para "${searchTerm}"`);
                } else {
                    showAlert('success', `Mostrando ${result.equipos.length} equipos alquilados`);
                }
            } else {
                showAlert('danger', 'Error al buscar equipos: ' + result.message);
            }
        })
        .catch(error => {
            showAlert('danger', 'Error de conexión');
            console.error('Error:', error);
        });
    }

    function loadPendingEquipments() {
        console.log('Loading pending equipments...');
        currentFilter = 'pendientes';

        const searchInput = document.getElementById('search-input');
        if (searchInput) {
            searchInput.value = '';
        }

        const resultsContainer = document.getElementById('equipment-results');
        setLoadingState(resultsContainer, 'Cargando equipos pendientes...');

        return makeJsonRpcCall('/equipment/blocking/search', {
            search_term: '',
            only_pending: true
        })
        .then(result => {
            if (result.status === 'success') {
                const pendingEquipments = result.equipos.filter(eq => 
                    ['suspendido', 'bloqueado', 'no_accesible', 'pendiente_bloqueo', 'pendiente_desbloqueo'].includes(eq.estado_bloqueo)
                );
                displayEquipments(pendingEquipments);
                showAlert('warning', `${pendingEquipments.length} equipos requieren atención`);
            } else {
                showAlert('danger', 'Error al cargar equipos: ' + result.message);
            }
        })
        .catch(error => {
            showAlert('danger', 'Error de conexión');
            console.error('Error:', error);
        });
    }

    function refreshDashboard() {
        console.log('Refreshing dashboard...');

        // Mostrar indicador de actualización
        const refreshBtn = document.getElementById('refreshBtn');
        const originalHtml = refreshBtn ? refreshBtn.innerHTML : '';
        if (refreshBtn) {
            refreshBtn.disabled = true;
            refreshBtn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Actualizando...';
        }

        return makeJsonRpcCall('/equipment/blocking/dashboard_data', {})
            .then(result => {
                if (result.status === 'success') {
                    const data = result.data;
                    updateElement('equipos-activos', data.equipos_activos);
                    updateElement('equipos-suspendidos', data.equipos_suspendidos);
                    updateElement('equipos-bloqueados', data.equipos_bloqueados);
                    updateElement('equipos-no-accesibles', data.equipos_no_accesibles);
                    updateElement('pendientes-bloqueo', data.pendientes_bloqueo);
                    updateElement('pendientes-desbloqueo', data.pendientes_desbloqueo);

                    showAlert('success', 'Dashboard actualizado correctamente');

                    // Recargar vista actual según el filtro
                    if (currentFilter !== 'busqueda') {
                        setTimeout(() => {
                            switch(currentFilter) {
                                case 'todos':
                                    showAllEquipments();
                                    break;
                                case 'pendientes':
                                    loadPendingEquipments();
                                    break;
                                default:
                                    if (['activo', 'suspendido', 'bloqueado', 'no_accesible', 'pendiente_bloqueo', 'pendiente_desbloqueo'].includes(currentFilter)) {
                                        filterByStatus(currentFilter);
                                    } else {
                                        showAllEquipments();
                                    }
                            }
                        }, 500);
                    }
                }
            })
            .catch(error => {
                console.error('Error al actualizar dashboard:', error);
                showAlert('danger', 'Error al actualizar el dashboard');
            })
            .finally(() => {
                // Restaurar botón
                if (refreshBtn) {
                    refreshBtn.disabled = false;
                    refreshBtn.innerHTML = originalHtml;
                }
            });
    }

    function displayEquipments(equipos) {
        const resultsContainer = document.getElementById('equipment-results');
        if (!resultsContainer) return;

        updateResultsCount(equipos.length);

        if (equipos.length === 0) {
            let emptyMessage = 'No se encontraron equipos con los criterios especificados.';
            let emptyIcon = 'fas fa-inbox';

            // Mensaje personalizado según el filtro actual
            switch(currentFilter) {
                case 'activo':
                    emptyMessage = 'No hay equipos activos en este momento.';
                    emptyIcon = 'fas fa-check-circle';
                    break;
                case 'suspendido':
                    emptyMessage = 'No hay equipos suspendidos.';
                    emptyIcon = 'fas fa-pause-circle';
                    break;
                case 'bloqueado':
                    emptyMessage = 'No hay equipos bloqueados.';
                    emptyIcon = 'fas fa-lock';
                    break;
                case 'pendientes':
                    emptyMessage = 'No hay equipos pendientes de atención.';
                    emptyIcon = 'fas fa-check-circle';
                    break;
                case 'busqueda':
                    emptyMessage = 'No se encontraron equipos que coincidan con la búsqueda.';
                    emptyIcon = 'fas fa-search';
                    break;
            }

            resultsContainer.innerHTML = 
                '<div class="text-center py-5">' +
                    '<i class="' + emptyIcon + ' fa-3x text-muted mb-3"></i>' +
                    '<p class="text-muted">' + emptyMessage + '</p>' +
                    '<button type="button" class="btn btn-primary" onclick="showAllEquipments()">' +
                        '<i class="fas fa-list me-2"></i>Ver Todos los Equipos' +
                    '</button>' +
                '</div>';
            return;
        }

        const equipmentCards = equipos.map(equipo => {
            const motivoSection = equipo.motivo_bloqueo ? 
                '<div class="alert alert-info py-2 mb-3">' +
                    '<strong>Motivo:</strong> ' + escapeHtml(equipo.motivo_bloqueo) +
                '</div>' : '';

            const fechaSection = equipo.fecha_bloqueo ? 
                '<div class="text-muted small mb-3">' +
                    '<i class="fas fa-clock"></i> ' + escapeHtml(equipo.fecha_bloqueo) +
                '</div>' : '';

            const buttons = [];
            const equipoJsonStr = JSON.stringify(equipo).replace(/"/g, "&quot;").replace(/'/g, "&#x27;");

            if (equipo.puede_suspender) {
                buttons.push(
                    '<button class="btn btn-warning btn-sm" onclick="openActionModal(\'suspend\', ' + 
                    equipo.id + ', \'' + escapeHtml(equipo.serie) + '\', \'' + equipoJsonStr + '\')">' +
                        '<i class="fas fa-pause me-1"></i> Suspender' +
                    '</button>'
                );
            }
            if (equipo.puede_bloquear) {
                buttons.push(
                    '<button class="btn btn-danger btn-sm" onclick="openActionModal(\'block\', ' + 
                    equipo.id + ', \'' + escapeHtml(equipo.serie) + '\', \'' + equipoJsonStr + '\')">' +
                        '<i class="fas fa-lock me-1"></i> Bloquear' +
                    '</button>'
                );
            }
            if (equipo.puede_desbloquear) {
                buttons.push(
                    '<button class="btn btn-success btn-sm" onclick="openActionModal(\'unblock\', ' + 
                    equipo.id + ', \'' + escapeHtml(equipo.serie) + '\', \'' + equipoJsonStr + '\')">' +
                        '<i class="fas fa-unlock me-1"></i> Desbloquear' +
                    '</button>'
                );
            }

            return (
                '<div class="equipment-card">' +
                    '<div class="d-flex justify-content-between align-items-start mb-3">' +
                        '<div>' +
                            '<h5 class="mb-1 fw-bold">Serie: ' + escapeHtml(equipo.serie) + '</h5>' +
                            '<p class="text-muted mb-0">' + escapeHtml(equipo.cliente) + ' - ' + escapeHtml(equipo.modelo) + '</p>' +
                        '</div>' +
                        '<span class="status-badge status-' + equipo.estado_bloqueo + '">' +
                            escapeHtml(equipo.estado_label) +
                        '</span>' +
                    '</div>' +

                    '<div class="detail-grid">' +
                        '<div class="detail-item">' +
                            '<i class="fas fa-industry"></i>' +
                            '<span>Marca: ' + escapeHtml(equipo.marca) + '</span>' +
                        '</div>' +
                        '<div class="detail-item">' +
                            '<i class="fas fa-map-marker-alt"></i>' +
                            '<span>Dirección: ' + escapeHtml(equipo.direccion) + '</span>' +
                        '</div>' +
                        '<div class="detail-item">' +
                            '<i class="fas fa-network-wired"></i>' +
                            '<span>IP: ' + escapeHtml(equipo.ip_equipo || 'No configurada') + '</span>' +
                        '</div>' +
                        '<div class="detail-item">' +
                            '<i class="fas fa-wifi"></i>' +
                            '<span>Acceso remoto: ' + (equipo.acceso_remoto ? 'Disponible' : 'No disponible') + '</span>' +
                        '</div>' +
                    '</div>' +

                    motivoSection +
                    fechaSection +

                    '<div class="d-flex gap-2 justify-content-end flex-wrap">' +
                        buttons.join('') +
                    '</div>' +
                '</div>'
            );
        }).join('');

        resultsContainer.innerHTML = equipmentCards;
    }

    function openActionModal(action, equipmentId, serie, equipmentDataStr) {
        console.log('Opening action modal:', action, equipmentId);
        currentAction = action;
        currentEquipmentId = equipmentId;

        // Parsear los datos del equipo
        let equipment;
        try {
            if (typeof equipmentDataStr === 'string') {
                equipment = JSON.parse(equipmentDataStr.replace(/&quot;/g, '"').replace(/&#x27;/g, "'"));
            } else {
                equipment = equipmentDataStr;
            }
        } catch (e) {
            console.error('Error parsing equipment data:', e);
            equipment = {};
        }

        const modalTitle = document.getElementById('modalTitle');
        const motivoInput = document.getElementById('motivoInput');
        const confirmBtn = document.getElementById('confirmActionBtn');
        const equipmentDetails = document.getElementById('equipmentDetails');

        // Mostrar detalles del equipo
        updateElement('detailCliente', equipment.cliente || '');
        updateElement('detailModelo', equipment.modelo || '');
        updateElement('detailIP', equipment.ip_equipo || 'No configurada');

        const estadoElement = document.getElementById('detailEstado');
        if (estadoElement && equipment.estado_bloqueo) {
            estadoElement.innerHTML = '<span class="status-badge status-' + equipment.estado_bloqueo + '">' + (equipment.estado_label || '') + '</span>';
        }

        if (equipmentDetails) {
            equipmentDetails.style.display = 'block';
        }

        // Configurar según la acción
        switch(action) {
            case 'suspend':
                if (modalTitle) modalTitle.textContent = 'Suspender Servicio - Serie: ' + serie;
                if (motivoInput) motivoInput.setAttribute('placeholder', 'Motivo de la suspensión (ej: Mora de pagos, incumplimiento contractual...)');
                if (confirmBtn) {
                    confirmBtn.className = 'btn btn-warning';
                    confirmBtn.innerHTML = '<span id="btnLoading" class="d-none"><span class="spinner-border spinner-border-sm me-2"></span>Procesando...</span><span id="btnText"><i class="fas fa-pause me-2"></i>Suspender Servicio</span>';
                }
                break;
            case 'block':
                if (modalTitle) modalTitle.textContent = 'Bloquear Equipo - Serie: ' + serie;
                if (motivoInput) motivoInput.setAttribute('placeholder', 'Motivo del bloqueo remoto...');
                if (confirmBtn) {
                    confirmBtn.className = 'btn btn-danger';
                    confirmBtn.innerHTML = '<span id="btnLoading" class="d-none"><span class="spinner-border spinner-border-sm me-2"></span>Procesando...</span><span id="btnText"><i class="fas fa-lock me-2"></i>Bloquear Equipo</span>';
                }
                break;
            case 'unblock':
                if (modalTitle) modalTitle.textContent = 'Desbloquear Equipo - Serie: ' + serie;
                if (motivoInput) motivoInput.setAttribute('placeholder', 'Observaciones del desbloqueo...');
                if (confirmBtn) {
                    confirmBtn.className = 'btn btn-success';
                    confirmBtn.innerHTML = '<span id="btnLoading" class="d-none"><span class="spinner-border spinner-border-sm me-2"></span>Procesando...</span><span id="btnText"><i class="fas fa-unlock me-2"></i>Desbloquear Equipo</span>';
                }
                break;
        }

        // Limpiar modal y mostrar
        if (motivoInput) motivoInput.value = '';

        const modalAlert = document.getElementById('modalAlert');
        if (modalAlert) modalAlert.innerHTML = '';

        if (actionModal) {
            actionModal.show();
        }
    }

    function executeAction() {
        console.log('Executing action:', currentAction);
        const motivoInput = document.getElementById('motivoInput');
        const motivo = motivoInput ? motivoInput.value.trim() : '';
        const btnLoading = document.getElementById('btnLoading');
        const btnText = document.getElementById('btnText');
        const confirmBtn = document.getElementById('confirmActionBtn');

        // Validar motivo para acciones críticas
        if ((currentAction === 'suspend' || currentAction === 'block') && !motivo) {
            showModalAlert('warning', 'Por favor, proporciona un motivo para esta acción.');
            return;
        }

        // Mostrar loading
        if (btnLoading) btnLoading.classList.remove('d-none');
        if (btnText) btnText.classList.add('d-none');
        if (confirmBtn) confirmBtn.disabled = true;

        const endpoints = {
            'suspend': '/equipment/blocking/suspend',
            'block': '/equipment/blocking/block',
            'unblock': '/equipment/blocking/unblock'
        };

        return makeJsonRpcCall(endpoints[currentAction], {
            equipment_id: currentEquipmentId,
            motivo: motivo
        })
        .then(result => {
            if (result.status === 'success') {
                showModalAlert('success', result.message);

                // Cerrar modal después de 2 segundos y actualizar
                setTimeout(() => {
                    if (actionModal) {
                        actionModal.hide();
                    }
                    refreshDashboard();
                }, 2000);
            } else {
                showModalAlert('danger', result.message);
            }
        })
        .catch(error => {
            showModalAlert('danger', 'Error de conexión');
            console.error('Error:', error);
        })
        .finally(() => {
            // Ocultar loading
            if (btnLoading) btnLoading.classList.add('d-none');
            if (btnText) btnText.classList.remove('d-none');
            if (confirmBtn) confirmBtn.disabled = false;
        });
    }

    function showModalAlert(type, message) {
        const alertContainer = document.getElementById('modalAlert');
        if (!alertContainer) return;

        const alertClass = type === 'success' ? 'alert-success' : 
                        type === 'warning' ? 'alert-warning' : 'alert-danger';
        const icon = type === 'success' ? 'check-circle' : 
                type === 'warning' ? 'exclamation-triangle' : 'exclamation-triangle';

        alertContainer.innerHTML = 
            '<div class="alert ' + alertClass + ' d-flex align-items-center" role="alert">' +
                '<i class="fas fa-' + icon + ' me-2"></i>' +
                '<div>' + escapeHtml(message) + '</div>' +
            '</div>';
    }

    // Exponer funciones globalmente para onclick
    window.searchEquipments = searchEquipments;
    window.loadPendingEquipments = loadPendingEquipments;
    window.refreshDashboard = refreshDashboard;
    window.openActionModal = openActionModal;
    window.filterByStatus = filterByStatus;
    window.showAllEquipments = showAllEquipments;

    // Event Listeners para botones
    function setupEventListeners() {
        // Enter en búsqueda
        const searchInput = document.getElementById('search-input');
        if (searchInput) {
            searchInput.addEventListener('keypress', (e) => {
                if (e.which === 13) {
                    searchEquipments();
                }
            });

            // Búsqueda en tiempo real (opcional)
            searchInput.addEventListener('input', debounce((e) => {
                const value = e.target.value.trim();
                if (value.length >= 3) {
                    searchEquipments();
                } else if (value.length === 0) {
                    showAllEquipments();
                }
            }, 500));
        }

        // Botones principales
        const searchBtn = document.getElementById('searchBtn');
        const pendingBtn = document.getElementById('pendingBtn');
        const refreshBtn = document.getElementById('refreshBtn');
        const confirmBtn = document.getElementById('confirmActionBtn');

        if (searchBtn) {
            searchBtn.addEventListener('click', searchEquipments);
        }
        if (pendingBtn) {
            pendingBtn.addEventListener('click', loadPendingEquipments);
        }
        if (refreshBtn) {
            refreshBtn.addEventListener('click', refreshDashboard);
        }
        if (confirmBtn) {
            confirmBtn.addEventListener('click', executeAction);
        }

        // Shortcuts de teclado
        document.addEventListener('keydown', (e) => {
            // Ctrl/Cmd + K para buscar
            if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
                e.preventDefault();
                if (searchInput) searchInput.focus();
            }

            // F5 para actualizar dashboard
            if (e.key === 'F5') {
                e.preventDefault();
                refreshDashboard();
            }

            // Escape para cerrar modal
            if (e.key === 'Escape' && actionModal) {
                actionModal.hide();
            }
        });

        console.log('Event listeners configured');
    }

    // Función utilitaria para debounce
    function debounce(func, wait) {
        let timeout;
        return function executedFunction(...args) {
            const later = () => {
                clearTimeout(timeout);
                func(...args);
            };
            clearTimeout(timeout);
            timeout = setTimeout(later, wait);
        };
    }

    // Inicializar modal de Bootstrap
    function initializeModal() {
        const modalEl = document.getElementById('actionModal');
        if (modalEl && typeof bootstrap !== 'undefined') {
            actionModal = new bootstrap.Modal(modalEl, {
                backdrop: 'static',
                keyboard: false
            });
            console.log('Bootstrap modal initialized');
        } else {
            console.warn('Bootstrap not found or modal element missing');
        }
    }

    // Función para detectar si hay equipos pre-cargados
    function hasInitialEquipments() {
        const resultsContainer = document.getElementById('equipment-results');
        if (!resultsContainer) return false;

        return resultsContainer.querySelector('.equipment-card') !== null;
    }

    // Función de inicialización principal
    function initialize() {
        console.log('DOM Content Loaded - Initializing dashboard');
        initializeModal();
        setupEventListeners();

        // Cargar equipos automáticamente si no hay contenido inicial
        if (!hasInitialEquipments()) {
            console.log('No initial equipments found, loading all equipments...');
            showAllEquipments();
        } else {
            console.log('Initial equipments found, dashboard ready');
            // Actualizar contador basado en equipos existentes
            const existingCards = document.querySelectorAll('.equipment-card');
            updateResultsCount(existingCards.length);
            currentFilter = 'todos';
        }

        console.log('Equipment Blocking Dashboard initialized successfully');
    }

    // Inicializar cuando el DOM esté listo
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initialize);
    } else {
        initialize();
    }

    // Auto-refresh cada 5 minutos (opcional)
    setInterval(() => {
        console.log('Auto-refreshing dashboard data...');
        makeJsonRpcCall('/equipment/blocking/dashboard_data', {})
            .then(result => {
                if (result.status === 'success') {
                    const data = result.data;
                    updateElement('equipos-activos', data.equipos_activos);
                    updateElement('equipos-suspendidos', data.equipos_suspendidos);
                    updateElement('equipos-bloqueados', data.equipos_bloqueados);
                    updateElement('equipos-no-accesibles', data.equipos_no_accesibles);
                    updateElement('pendientes-bloqueo', data.pendientes_bloqueo);
                    updateElement('pendientes-desbloqueo', data.pendientes_desbloqueo);
                }
            })
            .catch(error => {
                console.error('Auto-refresh error:', error);
            });
    }, 300000); // 5 minutos

    // Debug info
    console.log('Equipment Blocking script loaded. Available functions:', {
        searchEquipments: typeof searchEquipments,
        loadPendingEquipments: typeof loadPendingEquipments,
        refreshDashboard: typeof refreshDashboard,
        openActionModal: typeof openActionModal,
        filterByStatus: typeof filterByStatus,
        showAllEquipments: typeof showAllEquipments,
        bootstrap: typeof bootstrap
    });

})();
//
